class GNNEncoder(nn.Module):
    def __init__(self, n_layers, hidden_dim, out_channels=1, aggregation='sum', norm='layer', learn_norm=True, track_norm=False, gated=True, sparse=False, use_activation_checkpoint=False, node_feature_only=False):
        super(GNNEncoder, self).__init__()
        self.sparse = sparse
        self.node_feature_only = node_feature_only
        self.hidden_dim = hidden_dim
        time_embed_dim = hidden_dim // 2
        self.node_embed = nn.Linear(hidden_dim, hidden_dim)
        self.edge_embed = nn.Linear(hidden_dim, hidden_dim)
        if not node_feature_only:
            self.pos_embed = PositionEmbeddingSine(hidden_dim // 2, normalize=True)
            self.edge_pos_embed = ScalarEmbeddingSine(hidden_dim, normalize=False)
        else:
            self.pos_embed = ScalarEmbeddingSine1D(hidden_dim, normalize=False)
        self.time_embed = nn.Sequential(nn.Linear(hidden_dim, time_embed_dim), nn.ReLU(), nn.Linear(time_embed_dim, time_embed_dim))
        self.out = nn.Sequential(normalize(hidden_dim), nn.ReLU(), nn.Conv2d(hidden_dim, out_channels, kernel_size=1, bias=True))
        self.layers = nn.ModuleList([GNNLayer(hidden_dim, aggregation, norm, learn_norm, track_norm, gated) for _ in range(n_layers)])
        self.time_embed_layers = nn.ModuleList([nn.Sequential(nn.ReLU(), nn.Linear(time_embed_dim, hidden_dim)) for _ in range(n_layers)])
        self.per_layer_out = nn.ModuleList([nn.Sequential(nn.LayerNorm(hidden_dim, elementwise_affine=learn_norm), nn.SiLU(), zero_module(nn.Linear(hidden_dim, hidden_dim))) for _ in range(n_layers)])
        self.use_activation_checkpoint = use_activation_checkpoint

