def __init__(self, env_name, n_layers, hidden_dim, aggregation, diffusion_type, diffusion_schedule, diffusion_steps, sparse_factor, use_activation_checkpoint, parallel_sampling, sequential_sampling, inference_diffusion_steps, inference_schedule, inference_trick, node_feature_only=False):
    super().__init__()
    self.problem_type = env_name
    self.diffusion_type = diffusion_type
    self.diffusion_schedule = diffusion_schedule
    self.diffusion_steps = diffusion_steps
    self.sparse = sparse_factor > 0 or node_feature_only
    self.sparse_factor = sparse_factor
    self.parallel_sampling = parallel_sampling
    self.sequential_sampling = sequential_sampling
    self.inference_diffusion_steps = inference_diffusion_steps
    self.inference_schedule = inference_schedule
    self.inference_trick = inference_trick
    if self.diffusion_type == 'gaussian':
        out_channels = 1
        self.diffusion = GaussianDiffusion(T=self.diffusion_steps, schedule=self.diffusion_schedule)
    elif self.diffusion_type == 'categorical':
        out_channels = 2
        self.diffusion = CategoricalDiffusion(T=self.diffusion_steps, schedule=self.diffusion_schedule, sparse=self.sparse)
    else:
        raise ValueError(f'Unknown diffusion type {self.diffusion_type}')
    self.model = GNNEncoder(n_layers=n_layers, hidden_dim=hidden_dim, out_channels=out_channels, aggregation=aggregation, sparse=self.sparse, use_activation_checkpoint=use_activation_checkpoint, node_feature_only=node_feature_only)
    self.num_training_steps_cached = None

