@staticmethod
def _pre_forward_compat(model, reset_state):
    problems = reset_state.problems
    model.log_scale = reset_state.log_scale
    k_full = int(model.k)
    k_now = min(k_full, problems.shape[2])
    row_vals = torch.topk(problems, k=k_now, dim=2, largest=False, sorted=True).values
    col_vals = torch.topk(problems.transpose(1, 2), k=k_now, dim=2, largest=False, sorted=True).values
    if k_now < k_full:
        row_pad = row_vals[..., -1:].expand(*row_vals.shape[:2], k_full - k_now)
        col_pad = col_vals[..., -1:].expand(*col_vals.shape[:2], k_full - k_now)
        row_vals = torch.cat([row_vals, row_pad], dim=2)
        col_vals = torch.cat([col_vals, col_pad], dim=2)
    row_emb = model.embedding_row(row_vals)
    col_emb = model.embedding_col(col_vals)
    (model.encoded_row, model.encoded_col) = model.encoder(row_emb, col_emb, problems, model.log_scale)
    model.decoder.set_kv(model.encoded_col)

