            self.embedding_node = MoE(input_size=5, output_size=embedding_dim, num_experts=MoE_param['num_experts'], k=MoE_param['topk'], T=1.0, noisy_gating=True, routing_level=MoE_param['routing_level'], routing_method=MoE_param['routing_method'], moe_model='Linear')
        else:
            self.embedding_depot = nn.Linear(2, embedding_dim)
            self.embedding_node = nn.Linear(5, embedding_dim)
