class Add_And_Normalization_Module(nn.Module):
    def __init__(self, embedding_dim=128, norm='batch', norm_loc='norm_last'):
        super().__init__()
        self.add = True if norm_loc == 'norm_last' else False
        if norm == 'batch':
            self.norm = nn.BatchNorm1d(embedding_dim, affine=True, track_running_stats=True)
        elif norm == 'batch_no_track':
            self.norm = nn.BatchNorm1d(embedding_dim, affine=True, track_running_stats=False)
        elif norm == 'instance':
            self.norm = nn.InstanceNorm1d(embedding_dim, affine=True, track_running_stats=False)
        elif norm == 'layer':
            self.norm = nn.LayerNorm(embedding_dim)
        elif norm == 'rezero':
            self.norm = torch.nn.Parameter(torch.Tensor([0.0]), requires_grad=True)
        else:
            self.norm = None

