class MoE(nn.Module):
    def expert_gating(self, x, k):
        x = x.mean(1) if self.routing_level == 'instance' else x
        logits = x @ self.w_gate
        S = torch.softmax(logits, dim=0)
        (G, I) = torch.topk(S.T, k=k, dim=-1)
        P = nn.functional.one_hot(I, num_classes=x.size(0))
        return (G, I, P)

