class AttentionModelDecoder(nn.Module):
    def forward(self, td: TensorDict, first_mode: str=None, **kwargs) -> Tuple[Tensor, Tensor]:
        weights = kwargs.get('weights')
        if self.env_name != 'cvrp' or (self.env_name == 'cvrp' and td.batch_size[1] > 1):
            pomo_size = kwargs.get('pomo_size', None)
            (selected, probs) = special_selected(self.env_name, {'td': td, 'first_mode': first_mode, 'first_placeholder': self.first_placeholder, 'pomo_size': pomo_size})
        if probs is None:
            q = reshape_by_heads(self.graph_mean_embedding + self.dynamic_embedding(self.encoded_nodes, td), head_num=self.num_heads)
            mask = td['next']['ninf_mask'].clone()
            if self.sub_glop:
                assert mask.shape[1] == 2, 'In glop,The AM pomo_size should be 2'
                problem_size = mask.shape[2]
                if td['next']['selected_count'][0, 0] == 0:
                    mask[:, 0, 1:problem_size] = float('-inf')
                    mask[:, 1, 0:problem_size - 1] = float('-inf')
                elif td['next']['selected_count'][0, 0] < problem_size - 1:
                    mask[:, 0, problem_size - 1] = float('-inf')
                    mask[:, 1, 0] = float('-inf')
                else:
                    mask[:, 0, problem_size - 1] = 0.0
                    mask[:, 1, 0] = 0.0
            out_concat = multi_head_attention(q, self.k, self.v, mask)
            if weights is None:
                mh_atten_out = self.multi_head_combine(out_concat)
            else:
                mh_atten_out = F.linear(out_concat, weights['decoder.multi_head_combine.weight'], bias=weights['decoder.multi_head_combine.bias'])
            penalty = kwargs.get('penalty', 0)
            probs = self.compatibility(mh_atten_out, self.encoded_nodes, mask=mask, logit_clipping=self.logit_clipping, penalty=penalty, sing_head_k=self.sing_head_k)
            selected = None
        return (selected, probs)

