        self.Wk = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.Wv = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        if self.model_params['num_experts'] > 1 and 'Dec' in self.model_params['expert_loc'] and (not self.ffidt):
            self.hierarchical_gating = True
            self.dense_or_moe = nn.Linear(head_num * qkv_dim, 2, bias=False)
            self.multi_head_combine_moe = MoE(input_size=head_num * qkv_dim, output_size=embedding_dim, num_experts=self.model_params['num_experts'], k=self.model_params['topk'], T=1.0, noisy_gating=True, routing_level=self.model_params['routing_level'], routing_method=self.model_params['routing_method'], moe_model='Linear')
            self.multi_head_combine_dense = nn.Linear(head_num * qkv_dim, embedding_dim)
        else:
            self.multi_head_combine_dense = nn.Linear(head_num * qkv_dim, embedding_dim)
        if self.ffidt:
            self.attr_mapping = nn.Linear(4, embedding_dim, bias=False)
            self.feed_forward = FeedForward(**model_params)
        self.k = None
        self.v = None
        self.single_head_key = None

